#!/usr/bin/env python3
"""Generate docs/subsystems/spel-map.md from tu_summary.csv. Usage: write_spel_map.py <output_root>"""
import csv, os, re, sys

R = sys.argv[1]
rows = list(csv.DictReader(open(os.path.join(R, 'decompiled/game__spel.dat/tu_summary.csv'), newline='')))
rows.sort(key=lambda r: r['first'])
G = [('AI', r'\\ai_|ai_mgr|AI_'), ('Cars', r'\\car_|\\Car_'), ('Camera, events', r'\\cm_|\\ev_'), ('2D and in-race effects', r'\\gfx_|\\Gfx_'), ('Game flow and player', r'\\gm_|\\Gm_|\\plr_|\\snd_'),
     ('Track objects and triggers', r'\\tob_|\\Tob_|\\Tr_|\\tr_'), ('Startup, menu animation, language', r'\\Main\.|Menuanim|lan_main'), ('Particles', r'\\Par_|\\par_|\\prt_'), ('Paths', r'\\pth_'), ('Animation', r'\\anm_'),
     ('Input, console, script glue', r'input\.CPP|console|RaceConsole|script\.cpp'), ('HUD and overlay', r'Hud_|Overlay|Ovl_|CTextureDetail'), ('Sound library', r'sound_lib'), ('Physics wrapper and support lib', r'DaviIpion|davisupportlib'),
     ('Race engine', r'Engine\\prog'), ('DX3D library', r'DX3D'), ('dxdraw library', r'dxdraw'), ('InputLib', r'InputLib')]
L = ['# spel.dat map', '', 'Generated by `scripts/write_spel_map.py` from `__FILE__` strings in the binary. Full per-function data: `decompiled/game__spel.dat/tu_map.csv`.', '',
     '## Confirmed', '', '- File names below appear as strings in `spel.dat`. "Direct" functions reference that string, usually for an error message.', '- Regions past `0x4cf000` are identified by strings in the code: `runtimelib`/`objectfile` messages (DaviScript), `IVP_` names (Ipion), `qh_` names and `ipion 99/07/10` (qhull), and MSVC runtime text.', '',
     '## Inferred', '', '- "Between" functions sit between two direct functions of one file, and the first and last addresses come from those functions. Inline and shared code can break this.', '- Library boundaries in the region table are approximate: they follow where these strings occur.', '',
     '## Unknown', '', '- 12,210 of 13,762 functions have no file assignment: mostly compiler funclets, library code and functions without a `__FILE__` string.', '', '## Regions', '',
     '| Range | Content | Evidence |', '|---|---|---|', '| `0x401000-0x4cefff` | Game, race engine, DX3D, dxdraw (table below) | `__FILE__` strings |', '| `0x4cf000-0x4ea0bf` | DaviScript runtime with some STL | runtime error strings, see `docs/formats/daviscript.md` |', '| `0x4ea0c0-0x4f1fff` | InputLib | `D:\\Work\\InputLib` strings |', '| `0x4f2000-~0x540000` | Ipion physics with qhull | `IVP_` and `qh_` strings |', '| `~0x540000-~0x560000` | STL and MSVC runtime | runtime strings, Function ID names |', '| `~0x560000-0x575fff` | Compiler exception funclets, many of a few bytes | `Unwind@`, `Catch@` names |', '', '## Source files by subsystem', '']
for name, pat in G:
    sel = [r for r in rows if re.search(pat, r['tu'])]
    if not sel:
        continue
    L += ['### ' + name, '', '| First | Last | Direct | Between | Bytes | Original file |', '|---|---|---|---|---|---|']
    for r in sel:
        L.append('| `%s` | `%s` | %s | %s | %s | `%s` |' % (r['first'], r['last'], r['direct'], r['between'], r['bytes'], r['tu'].replace('|', ' + ')))
    L.append('')
open(os.path.join(R, 'docs/subsystems/spel-map.md'), 'w').write('\n'.join(L))
print('tu rows', len(rows))
